/* NEIS Circle v6 — database-first conversations, replies, connections, search, circles and notifications. */
(function(){
const t=(en,arabic)=>state.lang==='ar'?arabic:en;
const same=(a,b)=>String(a)===String(b);
const byId=(arr,id)=>arr.find(x=>same(x.id,id));
const normalize=value=>String(value||'').toLocaleLowerCase(state.lang==='ar'?'ar':'en').normalize('NFKD').replace(/[\u064b-\u065f\u0670]/g,'').trim();
const match=(query,...values)=>!query||normalize(values.flat().join(' ')).includes(query);
const blank=(title,copy)=>`<div class="empty"><b>${title}</b><span>${copy}</span></div>`;
const normalizeSearch=normalize,matchesSearch=match,emptyState=blank;
const when=value=>new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value||Date.now()));
const relative=value=>{const sec=Math.max(0,(Date.now()-new Date(value).getTime())/1000);if(sec<60)return t('now','الآن');if(sec<3600)return `${Math.floor(sec/60)}${t('m','د')}`;if(sec<86400)return `${Math.floor(sec/3600)}${t('h','س')}`;return new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short'}).format(new Date(value))};
const safeError=(error,fallback)=>{console.error('[NEIS]',error);return window.neisFriendlyError?.(error,fallback)||t('Something went wrong. Please try again.','حدث خطأ. حاول مرة أخرى.')};
Object.assign(state,{follows:[],conversations:[],conversationMembers:[],liveMessages:[],circleRows:[],circleMembers:[],circleMessages:[],circleMeetings:[],notifications:[],reports:[],allComments:[],connectionTab:'following',searchTab:'all',searchResults:[],searchLoading:false,activeProfileId:'',activeConversationId:'',activeCircleId:'',circleTab:'home',circleFilter:'all',circleQuery:'',connectionsQuery:'',conversationQuery:'',dataErrors:{}});
let v6Channel=null,searchTimer=null,circleSearchTimer=null,searchIndex=-1;

function profileData(id){return state.members.find(x=>same(x.id,id))||{id,full_name:t('NEIS Student','طالب NEIS'),username:'student',grade:'',branch:'',bio:'',interests:[]}}
function profileAvatar(p,large=false){return avatar({name:p.full_name||p.name,initials:initials(p.full_name||p.name),color:'#006f5b'},large)}
function isFollowing(id){return state.follows.some(f=>same(f.follower_id,authUser?.id)&&same(f.following_id,id)&&f.status==='accepted')}
function followsMe(id){return state.follows.some(f=>same(f.follower_id,id)&&same(f.following_id,authUser?.id)&&f.status==='accepted')}
function membership(circleId,userId=authUser?.id){return state.circleMembers.find(m=>same(m.circle_id,circleId)&&same(m.user_id,userId))}
function canManageCircle(circleId){const m=membership(circleId);return !!(state.isAdmin||(m&&m.status==='active'&&['owner','admin'].includes(m.role)))}
function canModerateCircle(circleId){const m=membership(circleId);return !!(state.isAdmin||(m&&m.status==='active'&&['owner','admin','moderator'].includes(m.role)))}
function unreadMessages(){return state.conversations.reduce((sum,c)=>sum+conversationUnread(c.id),0)}
function conversationUnread(id){const member=state.conversationMembers.find(m=>same(m.conversation_id,id)&&same(m.user_id,authUser?.id)),read=member?.last_read_at||'1970-01-01';return state.liveMessages.filter(m=>same(m.conversation_id,id)&&!same(m.sender_id,authUser?.id)&&new Date(m.created_at)>new Date(read)).length}
function routeTo(path,replace=false){const hash='#/'+String(path||'home').replace(/^\/+/, '');if(location.hash===hash){applyRoute();return}(replace?history.replaceState(null,'',hash):history.pushState(null,'',hash));applyRoute()}

function applyRoute(){
  if(!authUser)return;
  const raw=location.hash.replace(/^#\/?/,'')||'home',[pathPart,queryPart='']=raw.split('?'),parts=pathPart.split('/').map(decodeURIComponent),head=parts[0];
  if(head==='profile'&&parts[1]){state.view='profile-detail';state.activeProfileId=parts[1]}
  else if(head==='messages'){state.view='messages';state.activeConversationId=parts[1]||state.activeConversationId||''}
  else if(head==='circles'&&parts[1]){state.view='circle-detail';state.activeCircleId=parts[1];state.circleTab=parts[2]||'home'}
  else if(head==='connections'){state.view='connections';state.connectionTab=parts[1]||'following'}
  else if(head==='search'){state.view='search';const q=new URLSearchParams(queryPart).get('q')||state.query;state.query=q;const input=$('#globalSearch');if(input)input.value=q;performSearch(q,false)}
  else if(head==='post'&&parts[1]){state.view='home';setTimeout(()=>comments(parts[1]),80)}
  else if(head==='admin'&&!state.isAdmin){history.replaceState(null,'','#/home');state.view='home';toast(t('The admin workspace is private.','مساحة الإدارة خاصة.'))}
  else{state.view=['home','discover','circles','messages','library','opportunities','gallery','articles','admin','notifications'].includes(head)?head:'home'}
  render();
}
const priorNav=nav;
nav=function(view){routeTo(view)};

const coreLoad=loadLiveData;
loadLiveData=async function(){
  if(!sb||!authUser)return;
  await coreLoad();
  const uid=authUser.id;
  const [followRes,myMembershipRes,circleRes,circleMemberRes,meetingRes,notificationRes,commentRes,reportRes]=await Promise.all([
    sb.from('follows').select('*').or(`follower_id.eq.${uid},following_id.eq.${uid}`).order('created_at',{ascending:false}),
    sb.from('conversation_members').select('*').eq('user_id',uid),
    sb.from('circles').select('*').order('created_at',{ascending:false}),
    sb.from('circle_members').select('*,profile:profiles(id,full_name,username,grade,branch,avatar_url)').order('joined_at'),
    sb.from('circle_meetings').select('*,creator:profiles(id,full_name,username,avatar_url)').order('starts_at'),
    sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(100),
    sb.from('comments').select('id,post_id,parent_id,author_id,body,created_at,updated_at,deleted_at,profile:profiles(id,full_name,username,grade,branch,avatar_url)').order('created_at'),
    state.isAdmin?sb.rpc('admin_report_details'):Promise.resolve({data:[],error:null})
  ]);
  if(!followRes.error)state.follows=followRes.data||[];else state.dataErrors.connections=followRes.error;
  let conversationIds=(myMembershipRes.data||[]).map(x=>x.conversation_id);
  let conversationRes={data:[]},memberRes={data:[]},messageRes={data:[]};
  if(conversationIds.length){[conversationRes,memberRes,messageRes]=await Promise.all([
    sb.from('conversations').select('*').in('id',conversationIds).order('updated_at',{ascending:false}),
    sb.from('conversation_members').select('*,profile:profiles(id,full_name,username,grade,branch,avatar_url)').in('conversation_id',conversationIds),
    sb.from('messages').select('*').in('conversation_id',conversationIds).order('created_at').limit(500)
  ])}
  if(!conversationRes.error)state.conversations=conversationRes.data||[];
  if(!memberRes.error)state.conversationMembers=memberRes.data||myMembershipRes.data||[];
  if(!messageRes.error)state.liveMessages=messageRes.data||[];
  if(!circleRes.error)state.circleRows=circleRes.data||[];else state.dataErrors.circles=circleRes.error;
  if(!circleMemberRes.error)state.circleMembers=circleMemberRes.data||[];
  if(!meetingRes.error)state.circleMeetings=meetingRes.data||[];else state.dataErrors.meetings=meetingRes.error;
  if(!notificationRes.error)state.notifications=notificationRes.data||[];
  if(!commentRes.error){state.allComments=commentRes.data||[];state.posts.forEach(p=>p.comments=state.allComments.filter(c=>same(c.post_id,p.id)&&!c.deleted_at).length)}
  if(!reportRes.error)state.reports=reportRes.data||[];
  const joinedCircleIds=state.isAdmin?state.circleRows.map(c=>c.id):state.circleMembers.filter(m=>same(m.user_id,uid)&&['active','muted'].includes(m.status)).map(m=>m.circle_id);
  state.circleMessages=[];
  if(joinedCircleIds.length){const cm=await sb.from('circle_messages').select('*,profile:profiles(id,full_name,username,avatar_url)').in('circle_id',joinedCircleIds).order('created_at').limit(500);if(!cm.error)state.circleMessages=cm.data||[]}
  if(v6Channel)await sb.removeChannel(v6Channel);
  v6Channel=sb.channel(`neis-v7-${uid}`).on('postgres_changes',{event:'*',schema:'public',table:'messages'},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'circle_messages'},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'circle_meetings'},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'notifications',filter:`user_id=eq.${uid}`},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'follows'},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'comments'},refreshV6).on('postgres_changes',{event:'*',schema:'public',table:'circle_members'},refreshV6).subscribe();
};
let refreshBusy=false;
async function refreshV6(){if(refreshBusy)return;refreshBusy=true;try{await loadLiveData();render()}finally{refreshBusy=false}}

const originalPostCard=postCard;
postCard=function(p){
  const liked=state.liked.map(String).includes(String(p.id)),saved=state.saved.map(String).includes(String(p.id));
  const deletable=p.is_live&&(same(p.author_id,authUser.id)||state.isAdmin||(p.circle_id&&canModerateCircle(p.circle_id)));
  return `<article class="post" id="post-${esc(p.id)}" data-post="${esc(p.id)}"><div class="post-top"><button class="author-link post-author" data-open-profile="${esc(p.author_id||'')}">${avatar(p)}<span class="post-person"><b>${esc(p.user)}</b><small>${esc(p.meta)} · ${esc(p.time)}</small></span></button><div class="post-meta-actions"><span class="post-kind">${esc(p.kind)}</span><div class="post-menu">${deletable?`<button class="danger" data-delete-post="${esc(p.id)}" aria-label="${t('Delete post','حذف المنشور')}">×</button>`:`<button data-report-target="post" data-report-id="${esc(p.id)}" aria-label="${t('Report post','الإبلاغ عن المنشور')}">•••</button>`}</div></div></div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p>${p.image_url?`<img class="upload-preview" style="margin-top:15px" src="${esc(p.image_url)}" alt="${esc(p.title)}" onerror="this.remove()">`:''}<div class="tag-row">${(p.tags||[]).map(tag=>`<button class="chip" data-topic="${esc(tag)}">#${esc(tag)}</button>`).join('')}</div><div class="post-actions"><button class="action ${liked?'active':''}" data-action="like" data-id="${esc(p.id)}">${icon('heart')}<span>${t('Helpful','مفيد')}</span><b>${p.likes}</b></button><button class="action" data-action="comments" data-id="${esc(p.id)}">${icon('chat')}<span>${t('Replies','الردود')}</span><b>${p.comments||0}</b></button><button class="action save ${saved?'active':''}" data-action="save" data-id="${esc(p.id)}">${icon('save')}<span>${saved?t('Saved','محفوظ'):t('Save','حفظ')}</span></button><button class="action" data-action="share" data-id="${esc(p.id)}">${icon('share')}<span>${t('Share','مشاركة')}</span></button></div></article>`
};

discover=function(){
  let people=state.members.filter(p=>!same(p.id,authUser.id)),q=normalize(state.query);
  if(q)people=people.filter(p=>match(q,p.full_name,p.username,p.grade,p.branch,p.interests,p.bio));
  if(state.discoverFilter==='Grade 11')people=people.filter(p=>p.grade==='Grade 11');
  if(state.discoverFilter==='Same branch')people=people.filter(p=>p.branch===state.profile.branch);
  if(state.discoverFilter==='Programming')people=people.filter(p=>normalize(p.interests).includes('programming'));
  return `${pageTitle(t('Discover people','اكتشف الطلاب'),t('Open any profile, follow people, or start a direct conversation.','افتح أي ملف شخصي أو تابع الطلاب أو ابدأ محادثة مباشرة.'))}<div class="tabs">${[['Recommended','مقترح'],['Grade 11','الصف 11'],['Same branch','نفس الفرع'],['Programming','البرمجة']].map(([v,a])=>`<button class="${state.discoverFilter===v?'active':''}" data-discover-filter="${v}">${t(v,a)}</button>`).join('')}</div><div class="grid-3 people-grid" style="margin-top:18px">${people.length?people.map(personCard).join(''):blank(t('No students found','لا يوجد طلاب'),t('Try another search or filter.','جرّب بحثًا أو فلترًا آخر.'))}</div>`
};
function personCard(p){return `<article class="module-card profile-card student-card" data-open-profile="${p.id}" tabindex="0"><div class="person-card-head">${profileAvatar(p,true)}<div><h3>${esc(p.full_name||'Student')}</h3><p class="person-handle">@${esc(p.username||'student')}</p></div></div><div class="person-tags"><span class="post-kind">${esc(p.grade||'Student')}</span><span class="branch-tag">${esc(p.branch||'NEIS')}</span></div><p class="person-interests">${esc((p.interests||[]).join(' · ')||p.bio||t('Learning and community','التعلم والمجتمع'))}</p><div class="profile-actions"><button class="secondary" data-v6-follow="${p.id}">${isFollowing(p.id)?t('Following ✓','تتم المتابعة ✓'):t('Follow','متابعة')}</button><button class="primary" data-message-user="${p.id}">${t('Message','مراسلة')}</button></div></article>`}

function profileView(){
  const p=profileData(state.activeProfileId),own=same(p.id,authUser.id),followers=state.follows.filter(f=>same(f.following_id,p.id)&&f.status==='accepted').length,following=state.follows.filter(f=>same(f.follower_id,p.id)&&f.status==='accepted').length,posts=state.posts.filter(x=>same(x.author_id,p.id));
  return `<section class="profile-hero">${profileAvatar(p,true).replace('large','large xl')}<div><div class="identity-line"><h1>${esc(p.full_name||'Student')}</h1>${p.role==='admin'?'<span class="badge-admin">Admin</span>':''}</div><p>@${esc(p.username||'student')} · ${esc(p.grade||'')} ${p.branch?`· ${esc(p.branch)}`:''}</p><p>${esc(p.bio||t('No bio yet.','لا توجد نبذة بعد.'))}</p><div class="profile-stats"><span><b>${followers}</b> ${t('followers','متابع')}</span><span><b>${following}</b> ${t('following','يتابع')}</span><span><b>${posts.length}</b> ${t('posts','منشور')}</span></div></div><div class="profile-hero-actions">${own?`<button class="primary" data-action="profile">${t('Edit profile','تعديل الملف')}</button>`:`<button class="secondary" data-v6-follow="${p.id}">${isFollowing(p.id)?t('Unfollow','إلغاء المتابعة'):t('Follow','متابعة')}</button><button class="primary" data-message-user="${p.id}">${t('Message','مراسلة')}</button><button class="secondary" data-report-target="profile" data-report-id="${p.id}">${t('Report','إبلاغ')}</button>`}</div></section><div class="page-title" style="margin-top:24px"><div><h2>${t('Posts','المنشورات')}</h2><p>${t('Public activity from this student.','النشاط العام لهذا الطالب.')}</p></div></div><div class="feed">${posts.length?posts.map(postCard).join(''):blank(t('No posts yet','لا توجد منشورات بعد'),t('Published posts will appear here.','ستظهر المنشورات هنا.'))}</div>`
}

function connectionsView(){
  const uid=authUser.id,tabs=[['following',t('Following','أتابعهم')],['followers',t('Followers','المتابعون')],['mutuals',t('Mutuals','متبادلون')],['requests',t('Requests','الطلبات')],['suggested',t('Suggested','مقترحون')]];
  const followingIds=state.follows.filter(f=>same(f.follower_id,uid)&&f.status==='accepted').map(f=>f.following_id),followerIds=state.follows.filter(f=>same(f.following_id,uid)&&f.status==='accepted').map(f=>f.follower_id),pendingIds=state.follows.filter(f=>same(f.following_id,uid)&&f.status==='pending').map(f=>f.follower_id);
  let ids=state.connectionTab==='following'?followingIds:state.connectionTab==='followers'?followerIds:state.connectionTab==='mutuals'?followingIds.filter(id=>followerIds.some(x=>same(x,id))):state.connectionTab==='requests'?pendingIds:state.members.filter(p=>!same(p.id,uid)&&!followingIds.some(id=>same(id,p.id))).map(p=>p.id);
  let people=ids.map(profileData);const q=normalize(state.connectionsQuery);if(q)people=people.filter(p=>match(q,p.full_name,p.username,p.grade,p.branch,p.interests));
  return `${pageTitle(t('Connections','العلاقات'),t('Everyone you follow, everyone following you, and useful suggestions.','كل من تتابعهم ومن يتابعونك واقتراحات مفيدة.'))}<label class="field" style="max-width:420px"><input id="connectionSearch" placeholder="${t('Search connections…','ابحث في العلاقات…')}" value="${esc(state.connectionsQuery)}"></label><div class="tabs">${tabs.map(([v,l])=>`<button class="${state.connectionTab===v?'active':''}" data-connection-tab="${v}">${l} <b>${v==='following'?followingIds.length:v==='followers'?followerIds.length:v==='requests'?pendingIds.length:''}</b></button>`).join('')}</div><div class="grid-3" style="margin-top:18px">${people.length?people.map(p=>state.connectionTab==='requests'?requestCard(p):personCard(p)).join(''):emptyState(t('Nobody here yet','لا يوجد أحد هنا بعد'),state.connectionTab==='following'?t('Discover students and follow the people you want to keep up with.','اكتشف الطلاب وتابع من تريد رؤية نشاطهم.'):t('This list will update automatically.','ستتحدث هذه القائمة تلقائيًا.'))}</div>`
}
function requestCard(p){return `<article class="module-card profile-card" data-open-profile="${p.id}" tabindex="0"><div class="identity-line">${profileAvatar(p,true)}<div><h3>${esc(p.full_name||'Student')}</h3><p>@${esc(p.username||'student')}</p></div></div><p>${esc(p.grade||'')} · ${esc(p.branch||'')}</p><div class="profile-actions"><button class="primary" data-follow-request="accept" data-user="${p.id}">${t('Accept','قبول')}</button><button class="secondary danger" data-follow-request="reject" data-user="${p.id}">${t('Reject','رفض')}</button></div></article>`}

function conversationName(id){const other=state.conversationMembers.find(m=>same(m.conversation_id,id)&&!same(m.user_id,authUser.id));return other?.profile||profileData(other?.user_id)}
function conversationLast(id){return state.liveMessages.filter(m=>same(m.conversation_id,id)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]}
messages=function(){
  let threads=[...state.conversations].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));const q=normalize(state.conversationQuery);if(q)threads=threads.filter(c=>match(q,conversationName(c.id)?.full_name,conversationName(c.id)?.username,conversationLast(c.id)?.body));const active=byId(state.conversations,state.activeConversationId)||threads[0];if(active&&!state.activeConversationId)state.activeConversationId=active.id;
  const activePerson=active?conversationName(active.id):null,msgs=active?state.liveMessages.filter(m=>same(m.conversation_id,active.id)):[];
  return `<section class="messages ${active?'mobile-thread-open':''}"><aside class="thread-list"><div class="thread-head"><h2>${t('Messages','الرسائل')}</h2><button class="round-btn" data-new-chat aria-label="${t('New conversation','محادثة جديدة')}">+</button></div><input id="conversationSearch" class="thread-search" placeholder="${t('Search conversations…','ابحث في المحادثات…')}" value="${esc(state.conversationQuery)}"><div class="thread-list-scroll">${threads.length?threads.map(c=>{const p=conversationName(c.id),last=conversationLast(c.id),unread=conversationUnread(c.id);return `<button class="thread ${active&&same(c.id,active.id)?'active':''}" data-open-conversation="${c.id}">${profileAvatar(p)}<div><b>${esc(p?.full_name||'Student')}</b><small>${esc(last?.deleted_at?t('Message deleted','تم حذف الرسالة'):last?.body||t('Start the conversation','ابدأ المحادثة'))}</small></div>${unread?`<i class="count-badge unread">${unread}</i>`:`<time>${last?relative(last.created_at):''}</time>`}</button>`}).join(''):emptyState(t('No conversations yet','لا توجد محادثات بعد'),t('Start a conversation with any student.','ابدأ محادثة مع أي طالب.'))}</div></aside><div class="chat">${active?`<div class="chat-head"><button class="round-btn" data-mobile-threads aria-label="${t('Back to conversations','العودة للمحادثات')}">←</button>${profileAvatar(activePerson)}<button class="author-link" data-open-profile="${activePerson?.id}"><span><b>${esc(activePerson?.full_name||'Student')}</b><small>@${esc(activePerson?.username||'student')}</small></span></button></div><div class="chat-flow" id="chatFlow">${msgs.length?msgs.map((m,i)=>messageBubble(m,msgs[i-1])).join(''):emptyState(t('No messages yet','لا توجد رسائل بعد'),t('Send the first message.','أرسل أول رسالة.'))}</div><form class="chat-form" id="liveChatForm"><input id="liveChatInput" maxlength="4000" required placeholder="${t('Write a message…','اكتب رسالة…')}" autocomplete="off" dir="auto"><button aria-label="${t('Send','إرسال')}">→</button></form>`:`<div class="chat-empty">${emptyState(t('Choose a conversation','اختر محادثة'),t('Select a conversation or start a new one.','اختر محادثة أو ابدأ واحدة جديدة.'))}</div>`}</div></section>`
};
function messageBubble(m,previous){const mine=same(m.sender_id,authUser.id),grouped=previous&&same(previous.sender_id,m.sender_id)&&(new Date(m.created_at)-new Date(previous.created_at)<300000);return `<div class="chat-message ${mine?'mine':''} ${grouped?'grouped':''} ${m.deleted_at?'deleted':''}">${profileAvatar(profileData(m.sender_id))}<span class="bubble ${mine?'mine':''}"><span class="message-text" dir="auto">${m.deleted_at?t('Message deleted','تم حذف الرسالة'):esc(m.body)}</span><time>${when(m.created_at)}${m.edited_at?` · ${t('edited','معدلة')}`:''}</time>${mine&&!m.deleted_at?`<button class="content-menu danger" data-delete-message="${m.id}" aria-label="${t('Delete message','حذف الرسالة')}">×</button>`:''}</span></div>`}

window.openNewConversation=function(){
  const people=state.members.filter(p=>!same(p.id,authUser.id));openModal(`<div class="modal-head"><div><h2>${t('New conversation','محادثة جديدة')}</h2><p>${t('Search and message a student directly. Following is not required.','ابحث عن طالب وراسله مباشرة دون اشتراط المتابعة.')}</p></div><button class="close" data-close>×</button></div><label class="field"><input id="newChatSearch" placeholder="${t('Search students…','ابحث عن الطلاب…')}"></label><div id="newChatPeople" class="result-list">${people.slice(0,20).map(newChatRow).join('')}</div>`);const input=$('#newChatSearch');input.oninput=()=>{const q=normalize(input.value);$('#newChatPeople').innerHTML=people.filter(p=>match(q,p.full_name,p.username,p.grade,p.branch)).slice(0,30).map(newChatRow).join('')||blank(t('No students found','لا يوجد طلاب'),t('Try another name.','جرّب اسمًا آخر.'));bindV6($('#modalRoot'))};bindV6($('#modalRoot'))
};
function newChatRow(p){return `<button class="result-row" data-message-user="${p.id}">${profileAvatar(p)}<div><h3>${esc(p.full_name||'Student')}</h3><p>@${esc(p.username||'student')} · ${esc(p.grade||'')} · ${esc(p.branch||'')}</p></div><span>→</span></button>`}
async function startConversation(userId){const existing=state.conversations.find(c=>state.conversationMembers.some(m=>same(m.conversation_id,c.id)&&same(m.user_id,userId)));let id=existing?.id;if(!id){const {data,error}=await sb.rpc('start_direct_conversation',{target_user:userId});if(error){toast(safeError(error,'start this conversation'));return}id=data}closeModal();await loadLiveData();state.activeConversationId=id;routeTo(`messages/${id}`);await markConversationRead(id)}
async function markConversationRead(id){await sb.from('conversation_members').update({last_read_at:new Date().toISOString()}).match({conversation_id:id,user_id:authUser.id});const mine=state.conversationMembers.find(m=>same(m.conversation_id,id)&&same(m.user_id,authUser.id));if(mine)mine.last_read_at=new Date().toISOString();updateBadges()}

circles=function(){
  let items=[...state.circleRows],q=normalize(state.query);if(q)items=items.filter(c=>match(q,c.name,c.description,c.category));
  if(state.circleFilter==='joined')items=items.filter(c=>membership(c.id)?.status==='active');
  if(state.circleFilter==='created')items=items.filter(c=>same(c.owner_id,authUser.id));
  return `${pageTitle(t('Circles','المجتمعات'),t('Real student communities with posts, chat, meetings and shared purpose.','مجتمعات طلابية حقيقية بها منشورات ودردشة واجتماعات وهدف مشترك.'),`<button class="primary" data-new-circle>${t('+ New circle','+ مجتمع جديد')}</button>`)}<div class="tabs"><button class="${state.circleFilter==='all'?'active':''}" data-circle-filter="all">${t('Explore','استكشف')}</button><button class="${state.circleFilter==='joined'?'active':''}" data-circle-filter="joined">${t('Joined','منضم إليها')}</button><button class="${state.circleFilter==='created'?'active':''}" data-circle-filter="created">${t('Created','أنشأتها')}</button></div><div class="grid-3" style="margin-top:18px">${items.length?items.map(circleCard).join(''):emptyState(t('No circles here yet','لا توجد مجتمعات هنا بعد'),state.circleFilter==='all'?t('Create the first Circle and it will open immediately.','أنشئ أول مجتمع وسيفتح فورًا.'):t('Change the filter or create a Circle.','غيّر الفلتر أو أنشئ مجتمعًا.'))}</div>`
};
function circleCard(c){const members=state.circleMembers.filter(m=>same(m.circle_id,c.id)&&m.status==='active').length,mine=membership(c.id);return `<article class="module-card profile-card" data-open-circle="${c.id}" role="link" tabindex="0" aria-label="${t('Open','فتح')} ${esc(c.name)}"><span class="module-icon" style="--tone:var(--accent2)">${esc((c.name||'NC').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><h3>${esc(c.name)}</h3><p>${esc(c.description||t('A student community.','مجتمع طلابي.'))}</p><div class="module-meta"><span>${esc(c.category)} · ${c.privacy==='private'?t('Private','خاص'):t('Public','عام')}</span><span>${members} ${t('members','أعضاء')}</span></div><button class="primary" data-open-circle="${c.id}">${mine?.status==='active'?t('Open circle','فتح المجتمع'):t('View circle','عرض المجتمع')}</button></article>`}
function circleView(){
  const c=byId(state.circleRows,state.activeCircleId);if(!c)return blank(t('Circle not found','المجتمع غير موجود'),t('It may have been removed or is private.','ربما تمت إزالته أو أصبح خاصًا.'));const mine=membership(c.id),members=state.circleMembers.filter(m=>same(m.circle_id,c.id)&&m.status==='active'),role=mine?.role||'visitor',roleLabel={owner:t('Owner','المالك'),admin:t('Admin','مشرف'),moderator:t('Moderator','منسق'),member:t('Member','عضو'),visitor:t('Visitor','زائر')}[role]||role,memberWord=members.length===1?t('member','عضو'):t('members','أعضاء');
  const tabs=[['home',t('Home','الرئيسية')],['posts',t('Posts','المنشورات')],['chat',t('Chat','الدردشة')],['meetings',t('Meetings','الاجتماعات')],['members',t('Members','الأعضاء')],['about',t('About','حول')]];
  return `<section class="circle-hero"><span class="module-icon circle-logo">${esc(c.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><div class="circle-hero-copy"><div class="identity-line"><h1>${esc(c.name)}</h1><span class="role-pill ${role}">${esc(roleLabel)}</span></div><p>${esc(c.description)}</p><div class="profile-stats"><span><b>${members.length}</b>${memberWord}</span><span>${esc(c.category)}</span><span>${c.privacy==='private'?t('Private','خاص'):t('Public','عام')}</span></div></div><div class="profile-hero-actions">${mine?.status==='active'?(role==='owner'?`<button class="primary" data-circle-tab="members">${t('Manage Circle','إدارة المجتمع')}</button>`:`<button class="secondary" data-v6-circle-leave="${c.id}">${t('Leave','مغادرة')}</button>`):`<button class="primary" data-v6-circle-join="${c.id}">${c.privacy==='private'?t('Request to join','طلب انضمام'):t('Join','انضمام')}</button>`}<button class="secondary" data-share-circle="${c.id}">${t('Share','مشاركة')}</button><button class="secondary" data-report-target="circle" data-report-id="${c.id}" aria-label="${t('More options','خيارات إضافية')}">•••</button></div></section><div class="tabs circle-tabs">${tabs.map(([v,l])=>`<button class="${state.circleTab===v?'active':''}" data-circle-tab="${v}">${l}</button>`).join('')}</div>${circleTabContent(c,mine,members)}`
}
function circleTabContent(c,mine,members){
  const query=normalize(state.circleQuery),allPosts=state.posts.filter(p=>same(p.circle_id,c.id)),posts=allPosts.filter(p=>match(query,p.title,p.body,p.tags,p.user)),filteredMembers=members.filter(m=>match(query,m.profile?.full_name,m.profile?.username,m.profile?.grade,m.profile?.branch,m.role));
  const search=`<div class="circle-toolbar"><label class="field"><input id="circleSearch" value="${esc(state.circleQuery)}" placeholder="${t('Search this Circle…','ابحث داخل المجتمع…')}"></label>${state.circleQuery?`<button class="secondary" data-clear-circle-search>${t('Clear','مسح')}</button>`:''}</div>`;
  if(state.circleTab==='home')return `${search}<div class="circle-layout"><div><div class="composer-bar">${profileAvatar(profileData(authUser.id))}<button ${mine?.status==='active'?'data-circle-compose':''}>${mine?.status==='active'?t('Start a discussion in this Circle…','ابدأ نقاشًا في هذا المجتمع…'):t('Join to participate','انضم للمشاركة')}</button></div><div class="feed" style="margin-top:16px">${posts.length?posts.slice(0,10).map(postCard).join(''):emptyState(t('No Circle posts yet','لا توجد منشورات بعد'),query?t('No posts match your search.','لا توجد منشورات مطابقة للبحث.'):mine?.status==='active'?t('Start the first discussion.','ابدأ أول نقاش.'):t('Join to follow the conversation.','انضم لمتابعة النقاش.'))}</div></div><aside class="circle-panel"><h3>${t('About this Circle','عن المجتمع')}</h3><p>${esc(c.description)}</p><p><b>${t('Category','التصنيف')}:</b> ${esc(c.category)}</p><p><b>${t('Created','تاريخ الإنشاء')}:</b> ${formatDate(c.created_at)}</p></aside></div>`;
  if(state.circleTab==='posts')return `${search}<div class="page-title"><div><h2>${t('Circle posts','منشورات المجتمع')}</h2><p>${posts.length} ${t('results','نتيجة')}</p></div>${mine?.status==='active'?`<button class="primary" data-circle-compose>${t('+ New post','+ منشور جديد')}</button>`:''}</div><div class="feed">${posts.length?posts.map(postCard).join(''):emptyState(t('No posts found','لا توجد منشورات'),query?t('Try a different search.','جرّب بحثًا مختلفًا.'):t('Start the first discussion.','ابدأ أول نقاش.'))}</div>`;
  if(state.circleTab==='chat'){const msgs=state.circleMessages.filter(m=>same(m.circle_id,c.id)&&match(query,m.body,m.profile?.full_name));return `${search}<section class="circle-panel circle-chat"><div class="section-head"><div><h2>${t('Circle chat','دردشة المجتمع')}</h2><p>${t('Messages update in realtime and remain after refresh.','الرسائل تتحدث لحظيًا وتبقى بعد تحديث الصفحة.')}</p></div></div><div class="chat-flow" id="circleChatFlow">${msgs.length?msgs.map((m,i)=>circleMessageBubble(m,msgs[i-1])).join(''):emptyState(t('No messages found','لا توجد رسائل'),query?t('Try another search.','جرّب بحثًا آخر.'):t('Start the group conversation.','ابدأ المحادثة الجماعية.'))}</div>${mine?.status==='active'&&mine.status!=='muted'?`<form class="chat-form" id="circleChatForm"><input id="circleChatInput" required maxlength="4000" placeholder="${t('Message the Circle…','اكتب للمجتمع…')}" dir="auto"><button aria-label="${t('Send','إرسال')}">→</button></form>`:`<div class="empty"><b>${t('Members only','للأعضاء فقط')}</b><span>${t('Join the Circle to chat.','انضم للمجتمع للمشاركة في الدردشة.')}</span></div>`}</section>`}
  if(state.circleTab==='meetings'){const meetings=state.circleMeetings.filter(m=>same(m.circle_id,c.id)&&!m.cancelled_at&&match(query,m.title,m.description,m.creator?.full_name));return `${search}<div class="page-title"><div><h2>${t('Online meetings','الاجتماعات الأونلاين')}</h2><p>${t('Free video rooms powered by Jitsi Meet.','غرف فيديو مجانية عبر Jitsi Meet.')}</p></div>${mine?.status==='active'?`<button class="primary" data-new-meeting>${t('+ Schedule meeting','+ جدولة اجتماع')}</button>`:''}</div><div class="meeting-grid">${meetings.length?meetings.map(meetingCard).join(''):emptyState(t('No upcoming meetings','لا توجد اجتماعات قادمة'),query?t('Try another search.','جرّب بحثًا آخر.'):mine?.status==='active'?t('Schedule the first free meeting.','جدول أول اجتماع مجاني.'):t('Join the Circle to create meetings.','انضم للمجتمع لإنشاء الاجتماعات.'))}</div>`}
  if(state.circleTab==='members')return `${search}<div class="page-title"><div><h2>${t('Members','الأعضاء')}</h2><p>${filteredMembers.length} ${t('active members','عضو نشط')}</p></div></div><div class="result-list">${filteredMembers.length?filteredMembers.map(m=>`<div class="result-row">${profileAvatar(m.profile||profileData(m.user_id))}<div><h3><button class="author-link" data-open-profile="${m.user_id}">${esc(m.profile?.full_name||'Student')}</button></h3><p>@${esc(m.profile?.username||'student')} · ${esc(m.profile?.grade||'')} · ${esc(m.profile?.branch||'')}</p></div><div class="identity-line"><span class="role-pill ${m.role}">${esc(m.role)}</span>${canManageCircle(c.id)&&!same(m.user_id,authUser.id)&&m.role!=='owner'?`<select data-member-role="${m.user_id}"><option value="member" ${m.role==='member'?'selected':''}>Member</option><option value="moderator" ${m.role==='moderator'?'selected':''}>Moderator</option><option value="admin" ${m.role==='admin'?'selected':''}>Admin</option></select><button class="secondary danger" data-remove-member="${m.user_id}">${t('Remove','إزالة')}</button>`:''}</div></div>`).join(''):emptyState(t('No members found','لا يوجد أعضاء'),t('Try another search.','جرّب بحثًا آخر.'))}</div>`;
  return `<section class="circle-panel circle-about"><header class="circle-about-head"><h2>${t('About this Circle','حول هذا المجتمع')}</h2><p>${esc(c.description||t('A student community for learning and collaboration.','مجتمع طلابي للتعلم والتعاون.'))}</p></header><dl class="circle-facts"><div class="circle-fact"><dt>${t('Category','التصنيف')}</dt><dd>${esc(c.category)}</dd></div><div class="circle-fact"><dt>${t('Privacy','الخصوصية')}</dt><dd>${c.privacy==='private'?t('Private','خاص'):t('Public','عام')}</dd></div><div class="circle-fact"><dt>${t('Owner','المالك')}</dt><dd>${esc(profileData(c.owner_id).full_name||'Student')}</dd></div></dl>${canManageCircle(c.id)?`<div class="circle-management"><div><h3>${t('Circle management','إدارة المجتمع')}</h3><p>${t('Manage roles from Members, or permanently delete this Circle and its community data.','أدر الأدوار من تبويب الأعضاء، أو احذف هذا المجتمع وبياناته نهائيًا.')}</p></div><button class="secondary danger" data-delete-circle="${c.id}">${t('Delete Circle','حذف المجتمع')}</button></div>`:''}</section>`
}

function meetingCard(m){const d=new Date(m.starts_at),day=new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{day:'2-digit'}).format(d),month=new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{month:'short'}).format(d),manageable=same(m.creator_id,authUser.id)||canModerateCircle(m.circle_id),canJoin=membership(m.circle_id)?.status==='active'||state.isAdmin;return `<article class="meeting-card"><time class="meeting-date" datetime="${esc(m.starts_at)}"><b>${day}</b><span>${month}</span></time><div><h3>${esc(m.title)}</h3><p>${esc(m.description||t('Circle video meeting','اجتماع فيديو للمجتمع'))}</p><p>${when(m.starts_at)} · ${m.duration_minutes} ${t('min','دقيقة')} · ${t('by','بواسطة')} ${esc(m.creator?.full_name||profileData(m.creator_id).full_name)}</p><div class="meeting-actions">${canJoin?`<button class="primary" data-join-meeting="${m.id}">${t('Join meeting','دخول الاجتماع')}</button>`:`<button class="secondary" data-v6-circle-join="${m.circle_id}">${t('Join Circle to attend','انضم للمجتمع للحضور')}</button>`}${manageable?`<button class="secondary danger" data-delete-meeting="${m.id}">${t('Cancel','إلغاء')}</button>`:''}</div></div></article>`}
function circleMessageBubble(m,previous){const mine=same(m.sender_id,authUser.id),manageable=mine||canModerateCircle(m.circle_id),grouped=previous&&same(previous.sender_id,m.sender_id)&&(new Date(m.created_at)-new Date(previous.created_at)<300000);return `<div class="chat-message ${mine?'mine':''} ${grouped?'grouped':''} ${m.deleted_at?'deleted':''}">${profileAvatar(m.profile||profileData(m.sender_id))}<span class="bubble ${mine?'mine':''}"><span class="message-text" dir="auto">${m.deleted_at?t('Message deleted','تم حذف الرسالة'):esc(m.body)}</span><time>${when(m.created_at)}${m.edited_at?` · ${t('edited','معدلة')}`:''}</time>${!m.deleted_at&&manageable?`<button class="content-menu danger" data-delete-circle-message="${m.id}" aria-label="${t('Delete message','حذف الرسالة')}">×</button>`:''}</span></div>`}
function confirmAction(title,copy){return new Promise(resolve=>{openModal(`<div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(copy)}</p></div><button class="close" data-confirm-no>×</button></div><p class="confirm-copy">${t('This action is saved to the database and cannot be undone.','سيُحفظ هذا الإجراء في قاعدة البيانات ولا يمكن التراجع عنه.')}</p><div class="modal-actions"><button class="secondary" data-confirm-no>${t('Cancel','إلغاء')}</button><button class="primary danger" data-confirm-yes>${t('Delete','حذف')}</button></div>`);$$('[data-confirm-no]').forEach(b=>b.onclick=()=>{closeModal();resolve(false)});$('[data-confirm-yes]').onclick=()=>{closeModal();resolve(true)}})}
async function removeMediaUrl(url){if(!url)return;const marker='/storage/v1/object/public/community-media/',i=url.indexOf(marker);if(i<0)return;const path=decodeURIComponent(url.slice(i+marker.length));if(path)await sb.storage.from('community-media').remove([path])}
async function deletePost(id){const p=byId(state.posts,id);if(!p||!await confirmAction(t('Delete post?','حذف المنشور؟'),p.title))return;const {error}=await sb.from('posts').delete().eq('id',id);if(error){toast(safeError(error,'delete this post'));return}await removeMediaUrl(p.image_url);await loadLiveData();render();toast(t('Post deleted.','تم حذف المنشور.'))}
async function deleteGalleryItem(id){const g=byId(state.gallery,id);if(!g||!await confirmAction(t('Delete gallery item?','حذف عنصر المعرض؟'),(g.caption_en||g.caption_ar||t('This image','هذه الصورة'))))return;const {error}=await sb.from('gallery_items').delete().eq('id',id);if(error){toast(safeError(error,'delete this gallery item'));return}await removeMediaUrl(g.image_url);await loadLiveData();render();toast(t('Gallery item deleted.','تم حذف عنصر المعرض.'))}
async function deleteArticle(id){const a=byId(state.articles,id);if(!a||!await confirmAction(t('Delete article?','حذف المقال؟'),a.title_en||a.title_ar))return;const {error}=await sb.from('articles').delete().eq('id',id);if(error){toast(safeError(error,'delete this article'));return}await removeMediaUrl(a.cover_url);await loadLiveData();render();toast(t('Article deleted.','تم حذف المقال.'))}
async function deleteCircleMessage(id){const m=byId(state.circleMessages,id);if(!m||!await confirmAction(t('Delete message?','حذف الرسالة؟'),t('It will remain as a deleted-message marker.','ستبقى علامة توضح أن الرسالة حُذفت.')))return;const {error}=await sb.from('circle_messages').update({body:'',deleted_at:new Date().toISOString()}).eq('id',id);if(error){toast(safeError(error,'delete this message'));return}await loadLiveData();render()}
async function deleteDirectMessage(id){const m=byId(state.liveMessages,id);if(!m||!same(m.sender_id,authUser.id)||!await confirmAction(t('Delete message?','حذف الرسالة؟'),t('It will remain as a deleted-message marker.','ستبقى علامة توضح أن الرسالة حُذفت.')))return;const {error}=await sb.from('messages').update({body:'',deleted_at:new Date().toISOString()}).eq('id',id);if(error){toast(safeError(error,'delete this message'));return}await loadLiveData();render()}
async function deleteMeeting(id){const m=byId(state.circleMeetings,id);if(!m||!await confirmAction(t('Cancel meeting?','إلغاء الاجتماع؟'),m.title))return;const {error}=await sb.from('circle_meetings').delete().eq('id',id);if(error){toast(safeError(error,'cancel this meeting'));return}await loadLiveData();render();toast(t('Meeting cancelled.','تم إلغاء الاجتماع.'))}
async function deleteCircle(id){const c=byId(state.circleRows,id);if(!c||!canManageCircle(id)||!await confirmAction(t('Delete Circle?','حذف المجتمع؟'),t('Its chat, memberships and meetings will be removed. Circle posts will remain in the main community.','ستُحذف الدردشة والعضويات والاجتماعات، وستبقى منشورات المجتمع في المنصة الرئيسية.')))return;const button=document.querySelector(`[data-delete-circle="${CSS.escape(String(id))}"]`);if(button)button.disabled=true;let {data,error}=await sb.rpc('delete_circle',{target_circle:id});if(error&&String(error.message||'').includes('Could not find the function')){const direct=await sb.from('circles').delete().eq('id',id).select('id');error=direct.error;data=direct.data?.length>0}if(error||data!==true){if(button)button.disabled=false;toast(safeError(error||new Error('circle_delete_failed'),'delete this Circle'));return}state.circleRows=state.circleRows.filter(x=>!same(x.id,id));state.circleMembers=state.circleMembers.filter(x=>!same(x.circle_id,id));state.circleMessages=state.circleMessages.filter(x=>!same(x.circle_id,id));state.circleMeetings=state.circleMeetings.filter(x=>!same(x.circle_id,id));state.posts=state.posts.map(p=>same(p.circle_id,id)?{...p,circle_id:null}:p);state.activeCircleId=null;routeTo('circles');await loadLiveData();toast(t('Circle deleted.','تم حذف المجتمع.'))}
function scheduleMeeting(){const c=byId(state.circleRows,state.activeCircleId);openModal(`<div class="modal-head"><div><h2>${t('Schedule a free meeting','جدولة اجتماع مجاني')}</h2><p>${esc(c.name)} · Jitsi Meet</p></div><button class="close" data-close>×</button></div><form id="meetingForm"><label class="field">${t('Title','العنوان')}<input id="meetingTitle" required minlength="3" maxlength="120"></label><label class="field">${t('Description','الوصف')}<textarea id="meetingDescription" rows="3" maxlength="1000"></textarea></label><div class="row"><label class="field">${t('Date and time','التاريخ والوقت')}<input id="meetingStart" type="datetime-local" required></label><label class="field">${t('Duration','المدة')}<select id="meetingDuration"><option value="30">30 ${t('minutes','دقيقة')}</option><option value="60" selected>60 ${t('minutes','دقيقة')}</option><option value="90">90 ${t('minutes','دقيقة')}</option><option value="120">120 ${t('minutes','دقيقة')}</option></select></label></div><div class="modal-actions"><button type="button" class="secondary" data-close>${t('Cancel','إلغاء')}</button><button class="primary">${t('Create meeting','إنشاء الاجتماع')}</button></div></form>`);const input=$('#meetingStart'),minimum=new Date(Date.now()+5*60000);minimum.setMinutes(minimum.getMinutes()-minimum.getTimezoneOffset());input.min=minimum.toISOString().slice(0,16);input.value=minimum.toISOString().slice(0,16);$('#meetingForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const starts=new Date(input.value);if(starts.getTime()<Date.now()){toast(t('Choose a future time.','اختر وقتًا في المستقبل.'));button.disabled=false;return}const room=`NEISCircle_${c.id.replace(/-/g,'').slice(0,12)}_${crypto.randomUUID().replace(/-/g,'').slice(0,16)}`,{error}=await sb.from('circle_meetings').insert({circle_id:c.id,creator_id:authUser.id,title:$('#meetingTitle').value.trim(),description:$('#meetingDescription').value.trim(),starts_at:starts.toISOString(),duration_minutes:Number($('#meetingDuration').value),room_name:room});if(error){toast(safeError(error,'create this meeting'));button.disabled=false;return}closeModal();await loadLiveData();render();toast(t('Meeting scheduled.','تمت جدولة الاجتماع.'))}}
function joinMeeting(id){const m=byId(state.circleMeetings,id);if(!m)return;const room=encodeURIComponent(m.room_name),display=encodeURIComponent(state.profile.name||'NEIS Student'),url=`https://meet.jit.si/${room}#userInfo.displayName=%22${display}%22&config.prejoinPageEnabled=false&config.disableDeepLinking=true`;openModal(`<section class="meeting-room"><div class="modal-head"><div><h2>${esc(m.title)}</h2><p>${t('Free Circle video meeting','اجتماع فيديو مجاني للمجتمع')}</p></div><div class="meeting-room-actions"><a class="secondary meeting-popout" href="${url}" target="_blank" rel="noopener">${t('Open full screen','فتح بملء الشاشة')}</a><button class="close" data-close aria-label="${t('Close meeting','إغلاق الاجتماع')}">×</button></div></div><iframe title="${esc(m.title)}" src="${url}" allow="camera; microphone; fullscreen; display-capture; autoplay" referrerpolicy="no-referrer"></iframe></section>`,true);document.querySelector('#modalRoot .modal')?.classList.add('meeting-modal')}

galleryCard=function(g){const cap=(state.lang==='ar'?g.caption_ar:g.caption_en)||g.caption_en||g.caption_ar||t('Community moment','لحظة من المجتمع'),deletable=same(g.author_id,authUser.id)||state.isAdmin;return `<article class="gallery-card"><img src="${esc(g.image_url)}" alt="${esc(cap)}" loading="lazy" onerror="this.closest('article').classList.add('media-error');this.remove()"><div class="gallery-tools">${g.featured?`<span class="status-pill live">${t('Featured','مميز')}</span>`:''}${state.isAdmin&&!g.approved?`<button data-approve-gallery="${g.id}">${t('Approve','موافقة')}</button>`:''}${state.isAdmin?`<button data-feature-gallery="${g.id}">${g.featured?t('Unfeature','إلغاء التمييز'):t('Feature','تمييز')}</button>`:''}${deletable?`<button class="danger" data-delete-gallery="${g.id}">${t('Delete','حذف')}</button>`:''}</div><div class="gallery-copy"><div class="tag-row">${(g.tags||[]).slice(0,3).map(tag=>`<span>#${esc(tag)}</span>`).join('')}</div><h3>${esc(cap)}</h3><p>${esc(authorName(g.author))} · ${esc(authorMeta(g.author))}</p></div></article>`};
articleCard=function(a){const arabic=state.articleLanguage==='ar',title=(arabic?a.title_ar:a.title_en)||a.title_en||a.title_ar||t('Untitled','بدون عنوان'),excerpt=(arabic?a.excerpt_ar:a.excerpt_en)||a.excerpt_en||a.excerpt_ar||'',editable=same(a.author_id,authUser.id)||state.isAdmin;return `<article class="article-card"><div class="article-cover" style="background-image:${a.cover_url?`url('${esc(a.cover_url)}')`:mediaCardPlaceholder(title)}"></div><div class="article-copy"><div class="article-meta"><span class="post-kind">${a.status==='published'?t('Article','مقال'):t('Draft','مسودة')}</span><span>${formatDate(a.published_at||a.created_at)}</span></div><h3>${esc(title)}</h3><p>${esc(excerpt)}</p><button class="author-link" data-author="${a.author_id}">${avatar({name:authorName(a.author),initials:initials(authorName(a.author)),color:'#006f5b'})}<span>${esc(authorName(a.author))}<small style="display:block;color:var(--muted)">${esc(authorMeta(a.author))}</small></span></button><div class="article-actions"><button class="primary" data-read-article="${a.id}">${t('Read article','قراءة المقال')}</button>${editable?`<button class="secondary" data-edit-article="${a.id}">${t('Edit','تعديل')}</button><button class="secondary danger" data-delete-article="${a.id}">${t('Delete','حذف')}</button>`:''}</div></div></article>`};

newCircle=function(){if(!requireAccount())return;openModal(`<div class="modal-head"><div><h2>${t('Create a Circle','إنشاء مجتمع')}</h2><p>${t('Your Circle opens immediately and you become its owner.','يفتح المجتمع فورًا وتصبح أنت المالك.')}</p></div><button class="close" data-close>×</button></div><form id="createCircleForm"><label class="field">${t('Name','الاسم')}<input id="circleName" required minlength="3" maxlength="80"></label><label class="field">${t('Description','الوصف')}<textarea id="circleDescription" required rows="5" maxlength="1000"></textarea></label><div class="row"><label class="field">${t('Category','التصنيف')}<input id="circleCategory" value="General"></label><label class="field">${t('Privacy','الخصوصية')}<select id="circlePrivacy"><option value="public">${t('Public — anyone can view and join','عام — يمكن للجميع المشاهدة والانضمام')}</option><option value="private">${t('Private — membership requests','خاص — طلبات انضمام')}</option></select></label></div><div class="modal-actions"><button class="secondary" type="button" data-close>${t('Cancel','إلغاء')}</button><button id="createCircleSubmit" class="primary">${t('Create & open','إنشاء وفتح')}</button></div></form>`);$('#createCircleForm').onsubmit=async e=>{e.preventDefault();const button=$('#createCircleSubmit');button.disabled=true;button.textContent=t('Creating…','جارٍ الإنشاء…');const {data,error}=await sb.rpc('create_circle',{circle_name:$('#circleName').value.trim(),circle_description:$('#circleDescription').value.trim(),circle_category:$('#circleCategory').value.trim()||'General',circle_privacy:$('#circlePrivacy').value});if(error){toast(safeError(error,'create this Circle'));button.disabled=false;button.textContent=t('Create & open','إنشاء وفتح');return}const {data:created,error:readError}=await sb.from('circles').select('*').eq('id',data).single();if(readError||!created){toast(safeError(readError||new Error('circle_not_readable'),'open the new Circle'));button.disabled=false;button.textContent=t('Create & open','إنشاء وفتح');return}closeModal();await loadLiveData();if(!byId(state.circleRows,data))state.circleRows.unshift(created);routeTo(`circles/${data}/home`);toast(t('Circle created. You are the owner.','تم إنشاء المجتمع وأنت المالك.'))}}

async function performSearch(query,renderAfter=true){query=String(query||'').trim();if(query.length<2){state.searchResults=[];state.searchLoading=false;if(renderAfter&&state.view==='search')render();return}state.searchLoading=true;if(renderAfter&&state.view==='search')render();const {data,error}=await sb.rpc('global_search',{search_query:query,result_limit:30});state.searchLoading=false;if(error){state.dataErrors.search=error;state.searchResults=[];toast(safeError(error,'search'));}else{state.dataErrors.search=null;state.searchResults=Array.isArray(data)?data:[]}if(renderAfter&&state.view==='search')render();renderSuggestions()}
function searchView(){let items=state.searchResults;if(state.searchTab!=='all')items=items.filter(x=>x.type===state.searchTab);return `${pageTitle(`${t('Search','بحث')}: “${esc(state.query)}”`,t('Results from people, posts and Circles are queried securely from the database.','نتائج الطلاب والمنشورات والمجتمعات تأتي مباشرة من قاعدة البيانات.'))}<div class="tabs">${[['all',t('All','الكل')],['profile',t('People','الأشخاص')],['post',t('Posts','المنشورات')],['circle',t('Circles','المجتمعات')]].map(([v,l])=>`<button class="${state.searchTab===v?'active':''}" data-search-tab="${v}">${l}</button>`).join('')}</div><div class="result-list" style="margin-top:18px">${state.searchLoading?'<div class="loading-card"></div><div class="loading-card"></div>':state.dataErrors.search?`<div class="error-state">${t('Search could not load. Try again.','تعذر تحميل البحث. حاول مرة أخرى.')}</div>`:items.length?items.map(searchRow).join(''):emptyState(t('No results','لا توجد نتائج'),t('Try a different phrase or spelling.','جرّب عبارة أو كتابة مختلفة.'))}</div>`}
function highlight(value){const q=state.query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return q?esc(value).replace(new RegExp(`(${q})`,'ig'),'<mark>$1</mark>'):esc(value)}
function searchRow(x){return `<button class="result-row" data-search-open="${x.type}" data-search-id="${esc(x.id)}"><span class="entity-icon">${x.type==='profile'?'P':x.type==='post'?'POST':'C'}</span><div><h3>${highlight(x.title||'')}</h3><p>${esc(x.subtitle||'')} · ${highlight(x.preview||'')}</p></div>${x.created_at?`<time>${relative(x.created_at)}</time>`:'<span>→</span>'}</button>`}
function renderSuggestions(){const box=$('#searchSuggestions');if(!box)return;const q=$('#globalSearch')?.value.trim()||'';if(q.length<2||state.view==='search'){box.classList.add('hidden');return}const items=state.searchResults.slice(0,7);box.innerHTML=items.length?items.map((x,i)=>`<button class="suggest-item ${i===searchIndex?'active':''}" role="option" data-search-open="${x.type}" data-search-id="${esc(x.id)}"><span class="entity-icon">${x.type==='profile'?'P':x.type==='post'?'POST':'C'}</span><span><b>${highlight(x.title||'')}</b><small>${esc(x.preview||x.subtitle||'')}</small></span></button>`).join(''):`<div class="empty" style="padding:20px"><span>${t('No suggestions','لا توجد اقتراحات')}</span></div>`;box.classList.remove('hidden');bindV6(box)}

function notificationsView(){const unread=state.notifications.filter(n=>!n.read_at).length;return `${pageTitle(t('Notifications','الإشعارات'),t('Replies, messages, follows and Circle activity.','الردود والرسائل والمتابعات ونشاط المجتمعات.'),unread?`<button class="secondary" data-mark-all-read>${t('Mark all read','تحديد الكل كمقروء')}</button>`:'')}<div class="result-list">${state.notifications.length?state.notifications.map(n=>`<button class="notification-row ${n.read_at?'':'unread'}" data-open-notification="${n.id}" data-route="${esc(n.route||'notifications')}"><span class="entity-icon">${n.type==='message'?'M':n.type==='reply'?'R':'N'}</span><div><b>${esc(n.title)}</b><p>${esc(n.body)}</p></div><time>${relative(n.created_at)}</time></button>`).join(''):emptyState(t('No notifications','لا توجد إشعارات'),t('Meaningful activity will appear here.','سيظهر النشاط المهم هنا.'))}</div>`}

const originalAdmin=admin;
admin=function(){const base=originalAdmin();if(!state.isAdmin)return base;const content=[...state.posts.map(x=>({type:'post',id:x.id,title:x.title,meta:x.user,action:`data-delete-post="${x.id}"`})),...state.allComments.filter(x=>!x.deleted_at).map(x=>({type:'reply',id:x.id,title:x.body,meta:x.profile?.full_name||'Student',action:`data-delete-reply="${x.id}"`})),...state.circleRows.map(x=>({type:'circle',id:x.id,title:x.name,meta:profileData(x.owner_id).full_name,action:`data-delete-circle="${x.id}"`})),...state.circleMeetings.map(x=>({type:'meeting',id:x.id,title:x.title,meta:x.creator?.full_name||'Student',action:`data-delete-meeting="${x.id}"`})),...state.circleMessages.filter(x=>!x.deleted_at).map(x=>({type:'circle message',id:x.id,title:x.body,meta:x.profile?.full_name||'Student',action:`data-delete-circle-message="${x.id}"`})),...state.gallery.map(x=>({type:'gallery',id:x.id,title:x.caption_en||x.caption_ar||'Gallery item',meta:authorName(x.author),action:`data-delete-gallery="${x.id}"`})),...state.articles.map(x=>({type:'article',id:x.id,title:x.title_en||x.title_ar||'Article',meta:authorName(x.author),action:`data-delete-article="${x.id}"`}))];return `${base}<section class="module-card" style="margin-top:18px"><div class="page-title"><div><h2>${t('Reports','البلاغات')}</h2><p>${t('Identity data is private and visible only to authorized administrators.','بيانات الهوية خاصة ولا تظهر إلا للمسؤولين المصرح لهم.')}</p></div></div>${state.reports.length?`<div class="admin-report-list">${state.reports.map(r=>`<article class="admin-report-card"><div class="admin-report-head"><span class="entity-icon">${esc(r.target_type)}</span><div><h3>${esc(r.reason)}</h3><p>${esc(r.target_type)} · ${esc(r.target_id)} · ${when(r.created_at)}</p></div><select aria-label="${t('Report status','حالة البلاغ')}" data-report-status="${r.id}">${['open','reviewed','resolved','dismissed'].map(s=>`<option value="${s}" ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="admin-identity-grid"><div><small>${t('Reported account','الحساب المُبلّغ عنه')}</small><b>${esc(r.reported_display_name||t('Unavailable','غير متاح'))}</b><span>@${esc(r.reported_username||'—')} · ${esc(r.reported_user_id||'—')}</span></div><div><small>${t('Private identity','الهوية الخاصة')}</small><b>${esc(r.reported_email||t('No verified email','لا يوجد بريد موثق'))} · ${r.reported_email_verified?t('Email verified','البريد موثّق'):t('Email unavailable','البريد غير متاح')}</b><span>${esc(r.reported_phone||t('No registered phone','لا يوجد هاتف مسجّل'))} · ${r.reported_phone_validated?t('Phone registered / validated','الهاتف مسجّل / تم التحقق من صيغته'):t('Phone unavailable','الهاتف غير متاح')}</span></div></div><div class="admin-report-content"><small>${t('Reported content','المحتوى المُبلّغ عنه')}</small><p>${esc(r.reported_content||t('Content unavailable','المحتوى غير متاح'))}</p></div><p class="admin-report-details">${esc(r.details||'')}</p><footer>${t('Reporter','المُبلّغ')}: ${esc(r.reporter_display_name||'Student')} · @${esc(r.reporter_username||'student')}</footer></article>`).join('')}</div>`:emptyState(t('No reports','لا توجد بلاغات'),t('The moderation queue is clear.','قائمة المراجعة فارغة.'))}</section><section class="module-card" style="margin-top:18px"><div class="page-title"><div><h2>${t('Content moderation','إدارة المحتوى')}</h2><p>${t('Real database content only. Deletions require confirmation.','محتوى قاعدة البيانات الحقيقي فقط، والحذف يتطلب تأكيدًا.')}</p></div></div><div class="admin-content-list">${content.length?content.slice(0,100).map(x=>`<div class="admin-content-row"><div><b>${esc(x.title)}</b><p>${esc(x.type)} · ${esc(x.meta||'')}</p></div><button class="secondary danger" ${x.action}>${t('Delete','حذف')}</button></div>`).join(''):emptyState(t('No content','لا يوجد محتوى'),t('The production database is clean.','قاعدة بيانات الإنتاج نظيفة.'))}</div></section>`}

comments=async function(postId){
  const p=state.posts.find(x=>same(x.id,postId));if(!p)return;openModal(`<div class="modal-head"><div><h2>${t('Discussion','النقاش')}</h2><p>${esc(p.title)}</p></div><button class="close" data-close>×</button></div><div id="replyContent"><div class="loading-card"></div></div>`,true);
  const {data,error}=await sb.from('comments').select('id,post_id,parent_id,author_id,body,created_at,updated_at,deleted_at,profile:profiles(id,full_name,username,grade,branch,avatar_url)').eq('post_id',postId).order('created_at');
  if(error){$('#replyContent').innerHTML=`<div class="error-state">${t('Replies could not load. Try again.','تعذر تحميل الردود. حاول مرة أخرى.')}</div>`;return}
  const replies=data||[],renderNode=(r,depth=0)=>{const children=replies.filter(x=>same(x.parent_id,r.id)),own=same(r.author_id,authUser.id),deletable=own||state.isAdmin||(p.circle_id&&canModerateCircle(p.circle_id));return `<article class="reply-card ${depth?'nested':''}" id="reply-${r.id}"><div class="reply-head">${profileAvatar(r.profile||profileData(r.author_id))}<div><button class="author-link" data-open-profile="${r.author_id}"><b>${esc(r.profile?.full_name||'Student')}</b></button><small>@${esc(r.profile?.username||'student')} · ${when(r.created_at)}${r.updated_at&&r.updated_at!==r.created_at?` · ${t('edited','معدل')}`:''}</small></div></div><p class="reply-body">${r.deleted_at?`<i>${t('This reply was deleted.','تم حذف هذا الرد.')}</i>`:esc(r.body)}</p>${!r.deleted_at?`<div class="reply-actions"><button data-reply-to="${r.id}">${t('Reply','رد')}</button>${own?`<button data-edit-reply="${r.id}">${t('Edit','تعديل')}</button>`:''}${deletable?`<button data-delete-reply="${r.id}">${t('Delete','حذف')}</button>`:`<button data-report-target="comment" data-report-id="${r.id}">${t('Report','إبلاغ')}</button>`}</div>`:''}${children.map(c=>renderNode(c,depth+1)).join('')}</article>`};
  const roots=replies.filter(r=>!r.parent_id);$('#replyContent').innerHTML=`<div class="reply-tree">${roots.length?roots.map(r=>renderNode(r)).join(''):emptyState(t('No replies yet','لا توجد ردود بعد'),t('Start a useful discussion.','ابدأ نقاشًا مفيدًا.'))}</div><form id="replyForm" class="chat-form reply-composer"><input type="hidden" id="replyParent"><input id="replyInput" required maxlength="4000" placeholder="${t('Add a useful reply…','أضف ردًا مفيدًا…')}" dir="auto"><button aria-label="${t('Send reply','إرسال الرد')}">→</button></form>`;bindV6($('#modalRoot'));$('#replyForm').onsubmit=async e=>{e.preventDefault();const input=$('#replyInput'),button=$('#replyForm button'),body=input.value.trim();if(!body)return;button.disabled=true;const payload={post_id:postId,author_id:authUser.id,body,parent_id:$('#replyParent').value||null},{error}=await sb.from('comments').insert(payload);if(error){toast(safeError(error,'add your reply'));button.disabled=false;return}await loadLiveData();comments(postId);toast(t('Reply added.','تمت إضافة الرد.'))}
};

function openReport(type,id){openModal(`<div class="modal-head"><div><h2>${t('Report content','الإبلاغ عن محتوى')}</h2><p>${t('Reports go to the private admin queue.','تصل البلاغات إلى قائمة الأدمن الخاصة.')}</p></div><button class="close" data-close>×</button></div><form id="reportForm"><label class="field">${t('Reason','السبب')}<select id="reportReason"><option>${t('Spam','محتوى مزعج')}</option><option>${t('Harassment','إساءة أو مضايقة')}</option><option>${t('Unsafe content','محتوى غير آمن')}</option><option>${t('Other','سبب آخر')}</option></select></label><label class="field">${t('Details','التفاصيل')}<textarea id="reportDetails" rows="4" maxlength="1000"></textarea></label><div class="modal-actions"><button type="button" class="secondary" data-close>${t('Cancel','إلغاء')}</button><button class="primary">${t('Submit report','إرسال البلاغ')}</button></div></form>`);$('#reportForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('reports').insert({reporter_id:authUser.id,target_type:type,target_id:String(id),reason:$('#reportReason').value,details:$('#reportDetails').value.trim()});if(error){toast(safeError(error,'submit this report'));return}closeModal();toast(t('Report sent to the administrator.','تم إرسال البلاغ إلى الأدمن.'))}}

function openCirclePost(){const c=byId(state.circleRows,state.activeCircleId);openModal(`<div class="modal-head"><div><h2>${t('Post in','منشور في')} ${esc(c.name)}</h2></div><button class="close" data-close>×</button></div><form id="circlePostForm"><label class="field">${t('Type','النوع')}<select id="cpKind"><option>Discussion</option><option>Question</option><option>Resource</option><option>Announcement</option></select></label><label class="field">${t('Title','العنوان')}<input id="cpTitle" required maxlength="140"></label><label class="field">${t('Details','التفاصيل')}<textarea id="cpBody" required rows="6" maxlength="6000"></textarea></label><div class="row"><label class="field">${t('Tags','الوسوم')}<input id="cpTags"></label><label class="field">${t('Optional image','صورة اختيارية')}<input id="cpImage" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label></div><img id="cpImagePreview" class="upload-preview hidden" alt=""><div class="modal-actions"><button type="button" class="secondary" data-close>${t('Cancel','إلغاء')}</button><button class="primary">${t('Publish','نشر')}</button></div></form>`);$('#cpImage').onchange=e=>{const f=e.target.files[0];if(f){$('#cpImagePreview').src=URL.createObjectURL(f);$('#cpImagePreview').classList.remove('hidden')}};$('#circlePostForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true,file=$('#cpImage').files[0];let image_url='';if(file){image_url=await uploadMedia(file,`circles/${c.id}`);if(!image_url){button.disabled=false;return}}const {error}=await sb.from('posts').insert({author_id:authUser.id,circle_id:c.id,kind:$('#cpKind').value,title:$('#cpTitle').value.trim(),body:$('#cpBody').value.trim(),tags:$('#cpTags').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,8),image_url});if(error){if(image_url)await removeMediaUrl(image_url);toast(safeError(error,'publish this post'));button.disabled=false;return}closeModal();await loadLiveData();render();toast(t('Published in the Circle.','تم النشر في المجتمع.'))}}

home=function(){let posts=state.posts.filter(p=>!state.query||match(normalize(state.query),p.title,p.body,p.tags,p.user));if(state.filter==='Questions')posts=posts.filter(p=>p.kind==='Question');if(state.filter==='Resources')posts=posts.filter(p=>p.kind==='Resource');if(state.filter==='Latest')posts=[...posts].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));if(state.filter==='For you'){const following=state.follows.filter(f=>same(f.follower_id,authUser.id)&&f.status==='accepted').map(f=>f.following_id),joined=state.circleMembers.filter(m=>same(m.user_id,authUser.id)&&m.status==='active').map(m=>m.circle_id);posts=[...posts].sort((a,b)=>Number(same(b.author_id,authUser.id)||following.some(id=>same(id,b.author_id))||joined.some(id=>same(id,b.circle_id)))-Number(same(a.author_id,authUser.id)||following.some(id=>same(id,a.author_id))||joined.some(id=>same(id,a.circle_id)))||new Date(b.created_at)-new Date(a.created_at))}const latest=state.articles.filter(a=>a.status==='published').slice(0,2),suggested=state.members.filter(p=>!same(p.id,authUser.id)&&!isFollowing(p.id)).slice(0,3);return `<section class="hero"><div class="hero-main"><p class="kicker"><i></i>${t('Welcome back','مرحبًا بعودتك')}، ${esc(state.profile.name)}</p><h1>${t('Learn together. Build what matters.','نتعلم معًا ونبني ما يستحق.')}</h1><p>${t('Your feed is connected to people you follow and Circles you joined.','تغذيتك مرتبطة بمن تتابعهم والمجتمعات التي انضممت إليها.')}</p><div style="display:flex;gap:8px;margin-top:20px"><button class="primary" data-nav="circles">${t('Explore Circles','استكشف المجتمعات')}</button><button class="secondary" data-nav="connections">${t('Your connections','علاقاتك')}</button></div></div><div class="hero-side"><div class="pulse"><div><strong>${state.members.length}</strong><small>${t('real profiles','ملفات حقيقية')}</small></div><span class="pulse-orb"></span></div><div class="profile-meter"><div class="meter-row"><b>${t('Your identity','هويتك')}</b><strong>${esc(state.profile.grade||t('Student','طالب'))}</strong></div><small>${esc(state.profile.branch||t('Add your branch','أضف فرعك'))}</small><div class="bar"><i style="width:${state.profile.branch?'100':'55'}%"></i></div></div></div></section>${latest.length?`<section style="margin-bottom:22px"><div class="page-title" style="margin-bottom:14px"><div><p class="kicker"><i></i>${t('Editorial','المقالات')}</p><h2>${t('Latest articles','أحدث المقالات')}</h2></div><button class="secondary" data-nav="articles">${t('View all','عرض الكل')}</button></div><div class="article-grid">${latest.map(articleCard).join('')}</div></section>`:''}<div class="dashboard"><div class="main-column"><div class="composer-bar">${profileAvatar(profileData(authUser.id))}<button data-action="compose">${t('Share something useful…','شارك شيئًا مفيدًا…')}</button><button class="compose" data-action="compose">+</button></div><div class="tabs">${[['For you',t('For you','لك')],['Latest',t('Latest','الأحدث')],['Questions',t('Questions','أسئلة')],['Resources',t('Resources','مصادر')]].map(([v,l])=>`<button class="${state.filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><div class="feed">${posts.length?posts.map(postCard).join(''):emptyState(t('No posts yet','لا توجد منشورات بعد'),t('Create the first meaningful post.','أنشئ أول منشور مفيد.'))}</div></div><aside class="side-column"><section class="side-card"><h3>${t('Suggested people','أشخاص مقترحون')}</h3>${suggested.length?suggested.map(p=>`<div class="suggested-person"><button class="suggested-person-profile" data-open-profile="${p.id}">${profileAvatar(p)}<span class="suggested-person-copy"><b>${esc(p.full_name||'Student')}</b><small>${esc(p.grade||'')} · ${esc(p.branch||'')}</small></span></button><button class="suggested-person-follow" data-v6-follow="${p.id}" aria-label="${t('Follow','متاب��ة')} ${esc(p.full_name||'Student')}">+</button></div>`).join(''):blank(t('No suggestions','لا توجد اقتراحات'),t('Your network is up to date.','شبكتك محدثة.'))}</section><section class="side-card"><h3>${t('Your spaces','مساحاتك')}</h3><div class="account-menu"><button class="account-row" data-nav="gallery"><span>${t('Community gallery','معرض المجتمع')}</span><b>→</b></button><button class="account-row" data-nav="articles"><span>${t('Student journal','مجلة الطلاب')}</span><b>→</b></button></div></section></aside></div>`};
opportunities=function(){return `${pageTitle(t('Opportunities','الفرص'),t('Verified opportunities will appear here when publishing is enabled.','ستظهر الفرص الموثقة هنا عند تفعيل النشر.'))}${emptyState(t('No verified opportunities yet','لا توجد فرص موثقة بعد'),t('This page no longer displays demo events.','لم تعد هذه الصفحة تعرض فعاليات تجريبية.'))}`};

const baseRender=render;
render=function(){
  if(!authUser||state.onboardingComplete!==true){baseRender();return}
  const custom={connections:connectionsView,search:searchView,notifications:notificationsView,'profile-detail':profileView,'circle-detail':circleView};
  if(custom[state.view]){document.body.classList.add('app-ready');$('#view').innerHTML=custom[state.view]();$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.view));bindV6()}
  else{baseRender();bindV6()}
  updateBadges();requestAnimationFrame(()=>{const chat=$('#chatFlow')||$('#circleChatFlow');if(chat)chat.scrollTop=chat.scrollHeight});
};

function bindV6(root=document){
  root.querySelectorAll('[data-open-profile]').forEach(el=>{el.onclick=e=>{e.stopPropagation();const id=el.dataset.openProfile;if(id)routeTo(`profile/${id}`)}});
  root.querySelectorAll('[role="link"][tabindex="0"]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}});
  root.querySelectorAll('[data-v6-follow]').forEach(el=>el.onclick=async e=>{e.stopPropagation();const id=el.dataset.v6Follow,on=isFollowing(id);el.disabled=true;const q=on?sb.from('follows').delete().match({follower_id:authUser.id,following_id:id}):sb.from('follows').upsert({follower_id:authUser.id,following_id:id,status:'accepted'});const {error}=await q;if(error){toast(safeError(error,on?'unfollow':'follow'));el.disabled=false;return}await loadLiveData();render();toast(on?t('Unfollowed.','تم إلغاء المتابعة.'):t('Following.','تتم المتابعة.'))});
  root.querySelectorAll('[data-message-user]').forEach(el=>el.onclick=e=>{e.stopPropagation();startConversation(el.dataset.messageUser)});
  root.querySelectorAll('[data-open-conversation]').forEach(el=>el.onclick=()=>{state.activeConversationId=el.dataset.openConversation;routeTo(`messages/${state.activeConversationId}`);markConversationRead(state.activeConversationId)});
  root.querySelectorAll('[data-new-chat]').forEach(el=>el.onclick=openNewConversation);
  root.querySelectorAll('[data-mobile-threads]').forEach(el=>el.onclick=()=>{state.activeConversationId='';render()});
  root.querySelectorAll('[data-connection-tab]').forEach(el=>el.onclick=()=>routeTo(`connections/${el.dataset.connectionTab}`));
  root.querySelectorAll('[data-follow-request]').forEach(el=>el.onclick=async e=>{e.stopPropagation();const accepted=el.dataset.followRequest==='accept',q=accepted?sb.from('follows').update({status:'accepted'}).match({follower_id:el.dataset.user,following_id:authUser.id}):sb.from('follows').delete().match({follower_id:el.dataset.user,following_id:authUser.id}),{error}=await q;if(error){toast(safeError(error,accepted?'accept this request':'reject this request'));return}await loadLiveData();render();toast(accepted?t('Request accepted.','تم قبول الطلب.'):t('Request rejected.','تم رفض الطلب.'))});
  root.querySelectorAll('[data-open-circle]').forEach(el=>el.onclick=e=>{e.stopPropagation();routeTo(`circles/${el.dataset.openCircle}/home`)});
  root.querySelectorAll('[data-new-circle]').forEach(el=>el.onclick=newCircle);
  root.querySelectorAll('[data-circle-filter]').forEach(el=>el.onclick=()=>{state.circleFilter=el.dataset.circleFilter;render()});
  root.querySelectorAll('[data-circle-tab]').forEach(el=>el.onclick=()=>routeTo(`circles/${state.activeCircleId}/${el.dataset.circleTab}`));
  root.querySelectorAll('[data-circle-compose]').forEach(el=>el.onclick=openCirclePost);
  root.querySelectorAll('[data-new-meeting]').forEach(el=>el.onclick=scheduleMeeting);
  root.querySelectorAll('[data-join-meeting]').forEach(el=>el.onclick=()=>joinMeeting(el.dataset.joinMeeting));
  root.querySelectorAll('[data-delete-meeting]').forEach(el=>el.onclick=()=>deleteMeeting(el.dataset.deleteMeeting));
  root.querySelectorAll('[data-delete-post]').forEach(el=>el.onclick=()=>deletePost(el.dataset.deletePost));
  root.querySelectorAll('[data-delete-gallery]').forEach(el=>el.onclick=()=>deleteGalleryItem(el.dataset.deleteGallery));
  root.querySelectorAll('[data-delete-article]').forEach(el=>el.onclick=()=>deleteArticle(el.dataset.deleteArticle));
  root.querySelectorAll('[data-delete-circle]').forEach(el=>el.onclick=()=>deleteCircle(el.dataset.deleteCircle));
  root.querySelectorAll('[data-delete-message]').forEach(el=>el.onclick=()=>deleteDirectMessage(el.dataset.deleteMessage));
  root.querySelectorAll('[data-delete-circle-message]').forEach(el=>el.onclick=()=>deleteCircleMessage(el.dataset.deleteCircleMessage));
  root.querySelectorAll('[data-v6-circle-join]').forEach(el=>el.onclick=async()=>{const c=byId(state.circleRows,el.dataset.v6CircleJoin),status=c.privacy==='private'?'pending':'active';const {error}=await sb.from('circle_members').insert({circle_id:c.id,user_id:authUser.id,role:'member',status});if(error){toast(safeError(error,'join this Circle'));return}await loadLiveData();render();toast(status==='pending'?t('Membership request sent.','تم إرسال طلب الانضمام.'):t('Joined the Circle.','تم الانضمام للمجتمع.'))});
  root.querySelectorAll('[data-v6-circle-leave]').forEach(el=>el.onclick=async()=>{const m=membership(el.dataset.v6CircleLeave);if(m?.role==='owner'){toast(t('Transfer ownership before leaving.','انقل الملكية قبل المغادرة.'));return}if(!await confirmAction(t('Leave this Circle?','مغادرة المجتمع؟'),t('You can join again later if it is public.','يمكنك الانضمام مرة أخرى لاحقًا إذا كان عامًا.')))return;const {error}=await sb.from('circle_members').delete().match({circle_id:el.dataset.v6CircleLeave,user_id:authUser.id});if(error){toast(safeError(error,'leave this Circle'));return}await loadLiveData();render();toast(t('Left the Circle.','تمت مغادرة المجتمع.'))});
  root.querySelectorAll('[data-share-circle]').forEach(el=>el.onclick=async()=>{await navigator.clipboard.writeText(`${location.origin}${location.pathname}#/circles/${el.dataset.shareCircle}/home`);toast(t('Circle link copied.','تم نسخ رابط المجتمع.'))});
  root.querySelectorAll('[data-search-tab]').forEach(el=>el.onclick=()=>{state.searchTab=el.dataset.searchTab;render()});
  root.querySelectorAll('[data-search-open]').forEach(el=>el.onclick=()=>{const type=el.dataset.searchOpen,id=el.dataset.searchId;$('#searchSuggestions')?.classList.add('hidden');routeTo(type==='profile'?`profile/${id}`:type==='circle'?`circles/${id}/home`:`post/${id}`)});
  root.querySelectorAll('[data-open-notification]').forEach(el=>el.onclick=async()=>{await sb.from('notifications').update({read_at:new Date().toISOString()}).eq('id',el.dataset.openNotification);await loadLiveData();routeTo(el.dataset.route||'notifications')});
  root.querySelectorAll('[data-mark-all-read]').forEach(el=>el.onclick=async()=>{await sb.from('notifications').update({read_at:new Date().toISOString()}).is('read_at',null);await loadLiveData();render()});
  root.querySelectorAll('[data-report-target]').forEach(el=>el.onclick=e=>{e.stopPropagation();openReport(el.dataset.reportTarget,el.dataset.reportId)});
  root.querySelectorAll('[data-report-status]').forEach(el=>el.onchange=async()=>{const {error}=await sb.from('reports').update({status:el.value,reviewed_by:authUser.id,reviewed_at:new Date().toISOString()}).eq('id',el.dataset.reportStatus);if(error)toast(safeError(error,'update this report'));else{await loadLiveData();render()}});
  root.querySelectorAll('[data-reply-to]').forEach(el=>el.onclick=()=>{const r=byId(state.allComments,el.dataset.replyTo),input=$('#replyInput');$('#replyParent').value=el.dataset.replyTo;input.placeholder=`${t('Reply to','رد على')} ${r?.profile?.full_name||'Student'}…`;input.focus()});
  root.querySelectorAll('[data-edit-reply]').forEach(el=>el.onclick=async()=>{const r=byId(state.allComments,el.dataset.editReply),body=prompt(t('Edit your reply','عدّل ردك'),r?.body||'');if(!body?.trim())return;const {error}=await sb.from('comments').update({body:body.trim(),updated_at:new Date().toISOString()}).eq('id',r.id).eq('author_id',authUser.id);if(error)toast(safeError(error,'edit your reply'));else{await loadLiveData();comments(r.post_id)}});
  root.querySelectorAll('[data-delete-reply]').forEach(el=>el.onclick=async()=>{const r=byId(state.allComments,el.dataset.deleteReply);if(!r||!await confirmAction(t('Delete reply?','حذف الرد؟'),t('Replies below it will remain connected.','ستظل الردود المتفرعة مرتبطة به.')))return;const {error}=await sb.from('comments').update({deleted_at:new Date().toISOString(),body:''}).eq('id',r.id);if(error)toast(safeError(error,'delete this reply'));else{await loadLiveData();comments(r.post_id)}});
  root.querySelectorAll('[data-member-role]').forEach(el=>el.onchange=async()=>{const {error}=await sb.from('circle_members').update({role:el.value}).match({circle_id:state.activeCircleId,user_id:el.dataset.memberRole});if(error)toast(safeError(error,'change this role'));else{await loadLiveData();render()}});
  root.querySelectorAll('[data-remove-member]').forEach(el=>el.onclick=async()=>{const p=profileData(el.dataset.removeMember);if(!await confirmAction(t('Remove member?','إزالة العضو؟'),p.full_name||'Student'))return;const {error}=await sb.from('circle_members').delete().match({circle_id:state.activeCircleId,user_id:el.dataset.removeMember});if(error)toast(safeError(error,'remove this member'));else{await loadLiveData();render()}});
  root.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{$('#globalSearch').value=el.dataset.topic;state.query=el.dataset.topic;routeTo(`search?q=${encodeURIComponent(state.query)}`)});
  const cs=root.querySelector('#connectionSearch');if(cs)cs.oninput=()=>{state.connectionsQuery=cs.value;render()};
  const circleSearch=root.querySelector('#circleSearch');if(circleSearch)circleSearch.oninput=()=>{state.circleQuery=circleSearch.value;clearTimeout(circleSearchTimer);circleSearchTimer=setTimeout(()=>{render();requestAnimationFrame(()=>{const next=$('#circleSearch');if(next){next.focus();next.setSelectionRange(next.value.length,next.value.length)}})},180)};
  root.querySelectorAll('[data-clear-circle-search]').forEach(el=>el.onclick=()=>{state.circleQuery='';render()});
  const ts=root.querySelector('#conversationSearch');if(ts)ts.oninput=()=>{state.conversationQuery=ts.value;render()};
  const chat=root.querySelector('#liveChatForm');if(chat)chat.onsubmit=async e=>{e.preventDefault();const input=$('#liveChatInput'),button=chat.querySelector('button'),body=input.value.trim();if(!body)return;button.disabled=true;const {error}=await sb.from('messages').insert({conversation_id:state.activeConversationId,sender_id:authUser.id,body});if(error){toast(safeError(error,'send this message'));button.disabled=false;return}input.value='';await markConversationRead(state.activeConversationId);await loadLiveData();render()};
  const circleChat=root.querySelector('#circleChatForm');if(circleChat)circleChat.onsubmit=async e=>{e.preventDefault();const input=$('#circleChatInput'),button=circleChat.querySelector('button'),body=input.value.trim();if(!body)return;button.disabled=true;const {error}=await sb.from('circle_messages').insert({circle_id:state.activeCircleId,sender_id:authUser.id,body});if(error){toast(safeError(error,'send this message'));button.disabled=false;return}input.value='';await loadLiveData();render()};
}

function updateBadges(){const msg=unreadMessages(),not=state.notifications.filter(n=>!n.read_at).length;$$('[data-nav="messages"] i').forEach(i=>{i.className=msg?'count-badge':'';i.textContent=msg||''});const bell=$('[data-action="notifications"]');if(bell){let badge=bell.querySelector('.count-badge');if(not&&!badge){badge=document.createElement('i');badge.className='count-badge';bell.append(badge)}if(badge){badge.textContent=not||'';badge.classList.toggle('hidden',!not)}}}

const searchForm=$('#globalSearchForm'),searchInput6=$('#globalSearch');
if(searchForm)searchForm.onsubmit=e=>{e.preventDefault();const q=searchInput6.value.trim();if(q.length<2){toast(t('Type at least two characters.','اكتب حرفين على الأقل.'));return}state.query=q;routeTo(`search?q=${encodeURIComponent(q)}`)};
if(searchInput6){searchInput6.addEventListener('input',()=>{state.query=searchInput6.value;searchIndex=-1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>performSearch(searchInput6.value,false),260)});searchInput6.addEventListener('keydown',e=>{const items=$$('#searchSuggestions .suggest-item');if(e.key==='ArrowDown'){e.preventDefault();searchIndex=Math.min(items.length-1,searchIndex+1);renderSuggestions()}else if(e.key==='ArrowUp'){e.preventDefault();searchIndex=Math.max(0,searchIndex-1);renderSuggestions()}else if(e.key==='Enter'&&searchIndex>=0&&items[searchIndex]){e.preventDefault();items[searchIndex].click()}else if(e.key==='Escape')$('#searchSuggestions').classList.add('hidden')})}
window.addEventListener('hashchange',applyRoute);
document.addEventListener('click',e=>{if(!e.target.closest('#globalSearchForm'))$('#searchSuggestions')?.classList.add('hidden')});

setTimeout(async()=>{if(authUser){await loadLiveData();if(!location.hash)history.replaceState(null,'','#/home');applyRoute()}},250);
})();
